import { test, expect } from '@playwright/test';

test.describe('Email/Username Login Interchangeability', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should successfully log in with email or username interchangeably', async ({ page }) => {
    // Setup: Fill email field with valid email
    const emailInput = page.getByLabel('Email or Username');
    await emailInput.fill('user@example.com');

    // Setup: Fill password field with valid password
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('SecurePassword123');

    // Setup: Click login button
    const loginButton = page.getByRole('button', { name: /log in/i });
    await loginButton.click();

    // Verify success message appears
    const successMessage = page.getByText('Login successful');
    await expect(successMessage).toBeVisible();

    // Verify user is redirected to dashboard
    const dashboardLink = page.getByRole('link', { name: /dashboard/i });
    await expect(dashboardLink).toBeVisible();

    // Verify user is logged in
    const userNameDisplay = page.getByText('User');
    await expect(userNameDisplay).toBeVisible();

    // Reset and repeat with username
    await emailInput.fill('');
    await passwordInput.fill('');

    // Setup: Fill username field with valid username
    const usernameInput = page.getByLabel('Email or Username');
    await usernameInput.fill('john.doe');

    // Setup: Click login button again
    await loginButton.click();

    // Verify success message appears again
    await expect(successMessage).toBeVisible();

    // Verify user is redirected to dashboard
    await expect(dashboardLink).toBeVisible();

    // Verify user is logged in with username
    await expect(userNameDisplay).toContainText('John Doe');
  });

  test('should handle invalid email or username and display error messages', async ({ page }) => {
    // Setup: Fill email field with invalid email
    const emailInput = page.getByLabel('Email or Username');
    await emailInput.fill('invalid-email');

    // Setup: Fill password field with valid password
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('SecurePassword123');

    // Setup: Click login button
    const loginButton = page.getByRole('button', { name: /log in/i });
    await loginButton.click();

    // Verify error message appears for invalid email
    const errorMessage = page.getByText('Invalid email address');
    await expect(errorMessage).toBeVisible();

    // Verify login button is still clickable
    await expect(loginButton).toBeEnabled();

    // Reset and repeat with invalid username
    await emailInput.fill('');
    await passwordInput.fill('');

    // Setup: Fill username field with invalid username
    await usernameInput.fill('invalid-username');

    // Setup: Click login button again
    await loginButton.click();

    // Verify error message appears for invalid username
    await expect(errorMessage).toBeVisible();

    // Verify login button is still clickable
    await expect(loginButton).toBeEnabled();

    // Verify error message is displayed
    const errorDisplay = page.getByText('Invalid username');
    await expect(errorDisplay).toBeVisible();
  });
});
